namespace CreatorPay.Infrastructure.Checkout;

public sealed class CheckoutService(ApplicationDbContext db, IUtcClock clock, IPasswordHasher passwords, PasswordPolicyValidator policy, ICommissionEngine commissions, ICreatorEarningsService earnings, INotificationService notifications, IOptions<CheckoutOptions> configured, IOptions<WalletOptions> walletConfigured) : ICheckoutService
{
    readonly CheckoutOptions options = configured.Value;
    readonly WalletOptions walletOptions = walletConfigured.Value;
    public async Task<Guid> RegisterCustomerAsync(RegisterCustomerRequest r, CancellationToken ct) { if (r.Password != r.Confirmation) throw new ArgumentException("Passwords do not match."); var errors = policy.Validate(r.Password); if (errors.Count > 0) throw new ArgumentException(string.Join(" ", errors)); var phone = EthiopianMobileNumber.Normalize(r.PhoneNumber); var email = r.Email.Trim().ToUpperInvariant(); if (await db.UserAccounts.AnyAsync(x => x.NormalizedEmail == email, ct)) throw new InvalidOperationException("Email is already registered."); if (await db.Customers.AnyAsync(x => x.NormalizedPhoneNumber == phone, ct) || await db.Creators.AnyAsync(x => x.NormalizedPhoneNumber == phone, ct) || await db.Merchants.AnyAsync(x => x.NormalizedPhoneNumber == phone, ct)) throw new InvalidOperationException("Phone number is already registered."); var now = clock.UtcNow; var customer = new Customer { Id = Guid.NewGuid(), PublicCustomerId = $"CUS-{Guid.NewGuid():N}", DisplayName = r.DisplayName.Trim(), PhoneNumber = phone, NormalizedPhoneNumber = phone, CreatedAtUtc = now }; var user = new UserAccount { Id = Guid.NewGuid(), Email = r.Email.Trim(), NormalizedEmail = email, Role = UserRole.Customer, Status = AccountStatus.Active, CustomerId = customer.Id, IsEmailVerified = true, CreatedAtUtc = now }; user.PasswordHash = passwords.Hash(user, r.Password); db.Add(customer); db.Add(user); db.Add(new CustomerWallet { Id = Guid.NewGuid(), CustomerId = customer.Id, CurrencyCode = options.CurrencyCode, CreatedAtUtc = now }); Audit("CustomerRegistered", user.Id, customer.Id, null, now); await db.SaveChangesAsync(ct); return customer.Id; }
    public async Task<CheckoutDto> CreateAsync(Guid customer, string key, CreateCheckoutRequest r, CancellationToken ct) { Key(key); var old = await db.CheckoutSessions.SingleOrDefaultAsync(x => x.CustomerId == customer && x.CreateIdempotencyKey == key, ct); if (old != null) return Map(old); var now = clock.UtcNow; var c = await EligibleCampaign(r.CampaignId, now, ct); if (!await db.Customers.AnyAsync(x => x.Id == customer && x.Status == CustomerStatus.Active, ct)) throw new InvalidOperationException("Customer is not active."); var raw = Convert.ToHexString(RandomNumberGenerator.GetBytes(32)); var x = new CheckoutSession { Id = Guid.NewGuid(), PublicCheckoutId = $"CHK-{Guid.NewGuid():N}", CustomerId = customer, CampaignId = c.Id, MerchantId = c.MerchantId, CreatorId = c.CreatorId, TokenHash = Hash(raw), ExpiresAtUtc = now.AddMinutes(options.LifetimeMinutes), CreateIdempotencyKey = key, CreatedAtUtc = now }; db.Add(x); Audit("CheckoutCreated", null, customer, x.Id, now); await db.SaveChangesAsync(ct); return Map(x, $"creatorpay:checkout:{x.PublicCheckoutId}:{raw}"); }
    public async Task<CheckoutDto> PresentAsync(Guid merchant, Guid cashier, string key, PresentCheckoutRequest r, CancellationToken ct) { Key(key); if (r.PurchaseAmount <= 0) throw new ArgumentException("Purchase amount must be positive."); var p = r.QrPayload.Split(':'); if (p.Length != 4 || p[0] != "creatorpay" || p[1] != "checkout") throw new ArgumentException("Checkout QR is invalid."); var x = await db.CheckoutSessions.SingleOrDefaultAsync(a => a.PublicCheckoutId == p[2], ct) ?? throw new KeyNotFoundException("Checkout not found."); var now = clock.UtcNow; if (x.ExpiresAtUtc <= now || x.Status != CheckoutSessionStatus.Created) throw new InvalidOperationException("Checkout QR expired or was already used."); if (x.MerchantId != merchant) throw new UnauthorizedAccessException("Checkout belongs to another merchant."); if (Hash(p[3]) != x.TokenHash) throw new UnauthorizedAccessException("Checkout QR authentication failed."); if (!await db.CashierLocationAssignments.AnyAsync(a => a.CashierId == cashier && a.MerchantLocationId == r.MerchantLocationId && a.IsActive, ct)) throw new UnauthorizedAccessException("Cashier is not assigned to this location."); var preview = await commissions.PreviewAsync(new(r.PurchaseAmount, merchant, x.CreatorId, null, x.CampaignId, options.CurrencyCode, now), false, ct); x.PurchaseAmount = r.PurchaseAmount; x.ExpectedCreatorAmount = preview.Calculation.CreatorCommissionAmount; x.ExpectedCashbackAmount = preview.Calculation.CustomerCashbackAmount; x.CashierId = cashier; x.MerchantLocationId = r.MerchantLocationId; x.PresentedAtUtc = now; x.PresentIdempotencyKey = key; x.Status = CheckoutSessionStatus.AwaitingCustomerApproval; await Notify(x.CustomerId, NotificationType.CheckoutApprovalRequired, $"checkout:{x.Id}", "Confirm purchase", $"Approve {r.PurchaseAmount:0.00} ETB and earn {x.ExpectedCashbackAmount:0.00} ETB cashback.", x.Id, ct); Audit("CheckoutPresented", null, x.CustomerId, x.Id, now); await db.SaveChangesAsync(ct); return Map(x); }
    public async Task<CheckoutDto> ApproveAsync(Guid customer, Guid id, string key, CancellationToken ct) { Key(key); await using var tx = await db.Database.BeginTransactionAsync(IsolationLevel.Serializable, ct); var x = await db.CheckoutSessions.SingleOrDefaultAsync(a => a.Id == id && a.CustomerId == customer, ct) ?? throw new KeyNotFoundException("Checkout not found."); if (x.Status == CheckoutSessionStatus.Completed) return Map(x); var now = clock.UtcNow; if (x.Status != CheckoutSessionStatus.AwaitingCustomerApproval || x.ExpiresAtUtc <= now) throw new InvalidOperationException("Checkout cannot be approved."); var campaign = await db.CreatorMerchantCampaigns.Include(c => c.Partnership).SingleAsync(c => c.Id == x.CampaignId, ct); var merchant = await db.Merchants.SingleAsync(m => m.Id == x.MerchantId, ct); var creator = await db.Creators.SingleAsync(c => c.Id == x.CreatorId, ct); var customerRow = await db.Customers.SingleAsync(c => c.Id == customer, ct); if (campaign.Status != CampaignStatus.Active || campaign.StartsAtUtc > now || campaign.ExpiresAtUtc <= now || campaign.Partnership.Status != PartnershipStatus.Approved || merchant.Status != MerchantStatus.Active || creator.Status != CreatorStatus.Active || customerRow.Status != CustomerStatus.Active) throw new InvalidOperationException("Checkout participants are not active."); var calc = await commissions.PreviewAsync(new(x.PurchaseAmount!.Value, x.MerchantId, x.CreatorId, campaign.MerchantCreatorPartnershipId, x.CampaignId, options.CurrencyCode, now), false, ct); if (calc.Calculation.MerchantCommissionRatePercent != 10 || calc.Calculation.CreatorSharePercent != 40 || calc.Calculation.CustomerCashbackSharePercent != 30 || calc.Calculation.PlatformSharePercent != 30) throw new InvalidOperationException("Campaign must use the versioned 10% four-party commission rule."); var wallet = await db.MerchantWallets.SingleOrDefaultAsync(w => w.MerchantId == x.MerchantId && w.CurrencyCode == options.CurrencyCode, ct); var trial = await db.MerchantTrialCredits.SingleOrDefaultAsync(t => t.MerchantId == x.MerchantId, ct); var funded = wallet != null && wallet.AvailableBalance >= calc.Calculation.TotalCommissionAmount; if (!funded) { trial ??= new MerchantTrialCredit { Id = Guid.NewGuid(), MerchantId = x.MerchantId, CreatedAtUtc = now }; if (!trial.CanFund(calc.Calculation.TotalCommissionAmount)) throw new InvalidOperationException("Merchant funding is required."); if (db.Entry(trial).State == EntityState.Detached) db.Add(trial); trial.Use(calc.Calculation.TotalCommissionAmount, now); if (trial.Status == TrialCreditStatus.Exhausted) { merchant.Status = MerchantStatus.FundingRestricted; merchant.UpdatedAtUtc = now; Audit("MerchantTrialExhausted", null, customer, x.MerchantId, now); } } var snapshot = new CommissionCalculationSnapshot { Id = Guid.NewGuid(), CommissionRuleId = calc.RuleId, CommissionRuleVersionId = calc.RuleVersionId, CurrencyCode = options.CurrencyCode, PurchaseAmount = x.PurchaseAmount.Value, MerchantCommissionRatePercent = 10, TotalCommissionAmount = calc.Calculation.TotalCommissionAmount, CreatorSharePercent = 40, CreatorCommissionAmount = calc.Calculation.CreatorCommissionAmount, CustomerCashbackSharePercent = 30, CustomerCashbackAmount = calc.Calculation.CustomerCashbackAmount, PlatformSharePercent = 30, PlatformCommissionAmount = calc.Calculation.PlatformCommissionAmount, RoundingMode = calc.Calculation.RoundingMode, CalculatedAtUtc = now, RuleSourceType = calc.RuleSource, RuleSourceId = calc.RuleSourceId, CreatedAtUtc = now }; var purchase = new PurchaseTransaction { Id = Guid.NewGuid(), PublicTransactionId = $"CP-{Guid.NewGuid():N}", CreatorId = x.CreatorId, CustomerId = customer, CheckoutSessionId = x.Id, MerchantId = x.MerchantId, MerchantLocationId = x.MerchantLocationId!.Value, CashierId = x.CashierId!.Value, MerchantCreatorPartnershipId = campaign.MerchantCreatorPartnershipId, CampaignId = campaign.Id, CampaignQrCodeId = campaign.QrCode?.Id, CampaignCommissionRuleVersionId = campaign.CommissionRuleVersionId, CampaignStartsAtUtc = campaign.StartsAtUtc, CampaignExpiresAtUtc = campaign.ExpiresAtUtc, PurchaseAmount = x.PurchaseAmount.Value, CustomerCashbackAmount = calc.Calculation.CustomerCashbackAmount, CurrencyCode = options.CurrencyCode, CommissionCalculationSnapshotId = snapshot.Id, IdempotencyKey = key, TransactionDateUtc = now, CreatedAtUtc = now, CreatedByUserId = await db.UserAccounts.Where(u => u.CustomerId == customer).Select(u => u.Id).SingleAsync(ct), CorrelationId = key }; purchase.Confirm(now, purchase.CreatedByUserId); var cw = await db.CustomerWallets.SingleAsync(w => w.CustomerId == customer && w.CurrencyCode == options.CurrencyCode, ct); var cb = cw.Credit(calc.Calculation.CustomerCashbackAmount, now); if (cb.Recovered > 0) { var remainingRecovery = cb.Recovered; var recoveries = await db.CustomerRecoveryBalances.Where(r => r.CustomerId == customer && r.Status != CreatorRecoveryStatus.Recovered && r.Status != CreatorRecoveryStatus.Waived).OrderBy(r => r.CreatedAtUtc).ToListAsync(ct); foreach (var recovery in recoveries) { var applied = Math.Min(recovery.OutstandingAmount, remainingRecovery); recovery.OutstandingAmount -= applied; remainingRecovery -= applied; recovery.Status = recovery.OutstandingAmount == 0 ? CreatorRecoveryStatus.Recovered : CreatorRecoveryStatus.PartiallyRecovered; if (remainingRecovery == 0) break; } db.Add(new CustomerCashbackEntry { Id = Guid.NewGuid(), CustomerWalletId = cw.Id, CustomerId = customer, EntryType = CustomerCashbackEntryType.Recovery, Amount = cb.Recovered, BalanceBefore = cb.Before, BalanceAfter = cb.After, CurrencyCode = options.CurrencyCode, PurchaseTransactionId = purchase.Id, IdempotencyKey = $"recovery-offset:{purchase.Id}", CorrelationId = key, CreatedAtUtc = now }); } if (funded) { var merchantBalance = wallet!.Debit(calc.Calculation.TotalCommissionAmount, walletOptions.LowBalanceThreshold, now); db.Add(new MerchantWalletEntry { Id = Guid.NewGuid(), MerchantWalletId = wallet.Id, MerchantId = x.MerchantId, EntryType = MerchantWalletEntryType.CommissionDebit, Amount = calc.Calculation.TotalCommissionAmount, CurrencyCode = options.CurrencyCode, BalanceBefore = merchantBalance.Before, BalanceAfter = merchantBalance.After, RelatedTransactionId = purchase.Id, IdempotencyKey = $"checkout-debit:{purchase.Id}", Description = "Approved four-party checkout", CreatedAtUtc = now, CreatedByUserId = purchase.CreatedByUserId, CreatedBy = purchase.CreatedByUserId.ToString(), CorrelationId = key }); } db.Add(snapshot); db.Add(purchase); db.Add(new CustomerCashbackEntry { Id = Guid.NewGuid(), CustomerWalletId = cw.Id, CustomerId = customer, EntryType = CustomerCashbackEntryType.Earned, Amount = calc.Calculation.CustomerCashbackAmount, BalanceBefore = cb.Before, BalanceAfter = cb.After, CurrencyCode = options.CurrencyCode, PurchaseTransactionId = purchase.Id, IdempotencyKey = $"cashback:{purchase.Id}", CorrelationId = key, CreatedAtUtc = now }); db.Add(new PlatformRevenueEntry { Id = Guid.NewGuid(), PurchaseTransactionId = purchase.Id, Amount = calc.Calculation.PlatformCommissionAmount, CurrencyCode = options.CurrencyCode, IdempotencyKey = $"revenue:{purchase.Id}", CreatedAtUtc = now }); await earnings.RecordConfirmedPurchaseAsync(purchase.Id, x.CreatorId, snapshot.Id, calc.Calculation.CreatorCommissionAmount, options.CurrencyCode, now, key, ct); db.Add(Journal(purchase, calc.Calculation, now, funded, cb.Recovered)); x.Status = CheckoutSessionStatus.Completed; x.CustomerApprovedAtUtc = now; x.CompletedAtUtc = now; x.PurchaseTransactionId = purchase.Id; x.ApprovalIdempotencyKey = key; Audit("FourPartyPurchaseConfirmed", purchase.CreatedByUserId, customer, purchase.Id, now); await db.SaveChangesAsync(ct); await tx.CommitAsync(ct); await Notify(customer, NotificationType.CustomerCashbackEarned, $"cashback-notify:{purchase.Id}", "Cashback earned", $"{calc.Calculation.CustomerCashbackAmount:0.00} ETB cashback was added.", purchase.Id, ct); return Map(x); }
    public async Task<CheckoutDto> RejectAsync(Guid customer, Guid id, CancellationToken ct) { var x = await db.CheckoutSessions.SingleOrDefaultAsync(a => a.Id == id && a.CustomerId == customer, ct) ?? throw new KeyNotFoundException(); if (x.Status != CheckoutSessionStatus.AwaitingCustomerApproval) throw new InvalidOperationException("Checkout cannot be rejected."); x.Status = CheckoutSessionStatus.Rejected; await db.SaveChangesAsync(ct); return Map(x); }
    public async Task<IReadOnlyList<CheckoutDto>> GetCustomerCheckoutsAsync(Guid c, CancellationToken ct) => (await db.CheckoutSessions.Where(x => x.CustomerId == c).OrderByDescending(x => x.CreatedAtUtc).ToListAsync(ct)).Select(x => Map(x)).ToList();
    public async Task<CustomerWalletDto> GetWalletAsync(Guid c, CancellationToken ct) { var w = await db.CustomerWallets.SingleAsync(x => x.CustomerId == c, ct); return new(w.AvailableCashback, w.ReservedCashback, w.PaidLifetime, w.RecoveryBalance, w.CurrencyCode); }
    public async Task<CustomerPayoutDto> RequestPayoutAsync(Guid c, string key, CancellationToken ct) { Key(key); var old = await db.CustomerPayoutRequests.SingleOrDefaultAsync(x => x.CustomerId == c && x.IdempotencyKey == key, ct); if (old != null) return Map(old); await using var tx = await db.Database.BeginTransactionAsync(IsolationLevel.Serializable, ct); var w = await db.CustomerWallets.SingleAsync(x => x.CustomerId == c, ct); var before = w.AvailableCashback; var moved = w.ReserveFull(options.CashbackPayoutThreshold, clock.UtcNow); var p = new CustomerPayoutRequest { Id = Guid.NewGuid(), PublicPayoutId = $"CPAY-{Guid.NewGuid():N}", CustomerId = c, CustomerWalletId = w.Id, Amount = moved.Before, CurrencyCode = w.CurrencyCode, Status = CustomerPayoutStatus.Requested, RequestedAtUtc = clock.UtcNow, IdempotencyKey = key, CreatedAtUtc = clock.UtcNow }; db.Add(p); db.Add(new CustomerCashbackEntry { Id = Guid.NewGuid(), CustomerWalletId = w.Id, CustomerId = c, EntryType = CustomerCashbackEntryType.PayoutReserved, Amount = p.Amount, BalanceBefore = before, BalanceAfter = 0, CurrencyCode = w.CurrencyCode, CustomerPayoutRequestId = p.Id, IdempotencyKey = $"reserve:{p.Id}", CreatedAtUtc = clock.UtcNow }); await db.SaveChangesAsync(ct); await tx.CommitAsync(ct); return Map(p); }
    public async Task<IReadOnlyList<CustomerPayoutDto>> GetPayoutsAsync(Guid? c, CancellationToken ct) { var q = db.CustomerPayoutRequests.AsQueryable(); if (c.HasValue) q = q.Where(x => x.CustomerId == c); return (await q.OrderByDescending(x => x.RequestedAtUtc).ToListAsync(ct)).Select(Map).ToList(); }
    public async Task<CustomerPayoutDto> MarkPayoutProcessingAsync(Guid id, Guid actor, CancellationToken ct) { var p = await db.CustomerPayoutRequests.SingleAsync(x => x.Id == id, ct); if (p.Status != CustomerPayoutStatus.Requested) throw new InvalidOperationException("Payout is not awaiting processing."); p.Status = CustomerPayoutStatus.Processing; p.ProcessingAtUtc = clock.UtcNow; Audit("CustomerPayoutProcessing", actor, p.CustomerId, p.Id, clock.UtcNow); await db.SaveChangesAsync(ct); return Map(p); }
    public async Task<CustomerPayoutDto> MarkPayoutPaidAsync(Guid id, Guid actor, string key, MarkCustomerPayoutPaidRequest r, CancellationToken ct) { Key(key); await using var tx = await db.Database.BeginTransactionAsync(IsolationLevel.Serializable, ct); var p = await db.CustomerPayoutRequests.SingleAsync(x => x.Id == id, ct); if (p.Status == CustomerPayoutStatus.Paid) { if (p.PaymentConfirmationIdempotencyKey != key) throw new InvalidOperationException("Payout was already confirmed."); return Map(p); } if (p.Status != CustomerPayoutStatus.Processing) throw new InvalidOperationException("Payout must be processing."); var w = await db.CustomerWallets.SingleAsync(x => x.Id == p.CustomerWalletId, ct); var reservedBefore = w.ReservedCashback; w.MarkPaid(p.Amount, clock.UtcNow); db.Add(new CustomerCashbackEntry { Id = Guid.NewGuid(), CustomerWalletId = w.Id, CustomerId = p.CustomerId, EntryType = CustomerCashbackEntryType.PayoutPaid, Amount = p.Amount, BalanceBefore = reservedBefore, BalanceAfter = w.ReservedCashback, CurrencyCode = w.CurrencyCode, CustomerPayoutRequestId = p.Id, IdempotencyKey = $"paid:{p.Id}:{key}", CorrelationId = key, CreatedAtUtc = clock.UtcNow }); p.Status = CustomerPayoutStatus.Paid; p.PaidAtUtc = r.PaidAtUtc; p.ExternalMethod = r.ExternalMethod; p.ExternalReference = r.ExternalReference; p.PaymentConfirmationIdempotencyKey = key; var j = new FinancialJournal { Id = Guid.NewGuid(), Reference = $"CUSTOMER-PAYOUT-{p.PublicPayoutId}", Description = "Manual customer cashback payout", CreatedAtUtc = clock.UtcNow }; j.Lines.Add(Line(JournalAccount.CustomerCashbackPayable, JournalLineType.Debit, p.Amount, clock.UtcNow)); j.Lines.Add(Line(JournalAccount.PaymentClearing, JournalLineType.Credit, p.Amount, clock.UtcNow)); j.Post(clock.UtcNow); db.Add(j); Audit("CustomerPayoutPaid", actor, p.CustomerId, p.Id, clock.UtcNow); await db.SaveChangesAsync(ct); await tx.CommitAsync(ct); return Map(p); }
    public async Task<CustomerPayoutDto> MarkPayoutFailedAsync(Guid id, Guid actor, string reason, CancellationToken ct) { var p = await db.CustomerPayoutRequests.SingleAsync(x => x.Id == id, ct); if (p.Status != CustomerPayoutStatus.Processing) throw new InvalidOperationException("Payout must be processing."); var w = await db.CustomerWallets.SingleAsync(x => x.Id == p.CustomerWalletId, ct); var availableBefore = w.AvailableCashback; w.Release(p.Amount, clock.UtcNow); db.Add(new CustomerCashbackEntry { Id = Guid.NewGuid(), CustomerWalletId = w.Id, CustomerId = p.CustomerId, EntryType = CustomerCashbackEntryType.PayoutReleased, Amount = p.Amount, BalanceBefore = availableBefore, BalanceAfter = w.AvailableCashback, CurrencyCode = w.CurrencyCode, CustomerPayoutRequestId = p.Id, IdempotencyKey = $"released:{p.Id}", CreatedAtUtc = clock.UtcNow }); p.Status = CustomerPayoutStatus.Failed; p.FailedAtUtc = clock.UtcNow; p.FailureReason = reason; await db.SaveChangesAsync(ct); return Map(p); }
    public async Task<int> ExpireAsync(CancellationToken ct) { var now = clock.UtcNow; var expired = await db.CheckoutSessions.Where(x => x.ExpiresAtUtc <= now && (x.Status == CheckoutSessionStatus.Created || x.Status == CheckoutSessionStatus.AwaitingCustomerApproval)).ExecuteUpdateAsync(s => s.SetProperty(x => x.Status, CheckoutSessionStatus.Expired).SetProperty(x => x.UpdatedAtUtc, now), ct); var exhausted = db.MerchantTrialCredits.Where(x => x.Status == TrialCreditStatus.Exhausted).Select(x => x.MerchantId); await db.Merchants.Where(x => exhausted.Contains(x.Id) && x.Status == MerchantStatus.Active).ExecuteUpdateAsync(s => s.SetProperty(x => x.Status, MerchantStatus.FundingRestricted).SetProperty(x => x.UpdatedAtUtc, now), ct); return expired; }
    async Task<CreatorMerchantCampaign> EligibleCampaign(Guid id, DateTime now, CancellationToken ct)
    {
        var campaign = await db.CreatorMerchantCampaigns.Include(x => x.Partnership).SingleOrDefaultAsync(x => x.Id == id, ct) ?? throw new KeyNotFoundException("Campaign not found.");
        var merchantActive = await db.Merchants.AnyAsync(x => x.Id == campaign.MerchantId && x.Status == MerchantStatus.Active, ct);
        var creatorActive = await db.Creators.AnyAsync(x => x.Id == campaign.CreatorId && x.Status == CreatorStatus.Active, ct);
        var trialEligible = !await db.MerchantTrialCredits.AnyAsync(x => x.MerchantId == campaign.MerchantId && x.Status != TrialCreditStatus.Active, ct);
        var hasWalletFunding = await db.MerchantWallets.AnyAsync(x => x.MerchantId == campaign.MerchantId && x.CurrencyCode == options.CurrencyCode && x.AvailableBalance > 0, ct);
        if (campaign.Status != CampaignStatus.Active || campaign.StartsAtUtc > now || campaign.ExpiresAtUtc <= now || campaign.Partnership.Status != PartnershipStatus.Approved || !merchantActive || !creatorActive || (!trialEligible && !hasWalletFunding)) throw new InvalidOperationException("Campaign is not eligible for checkout.");
        return campaign;
    }
    async Task Notify(Guid customer, NotificationType type, string key, string title, string body, Guid entity, CancellationToken ct) { var user = await db.UserAccounts.Where(x => x.CustomerId == customer).Select(x => (Guid?)x.Id).SingleOrDefaultAsync(ct); if (user.HasValue) await notifications.CreateAsync(new(type, key, new Dictionary<string, string> { { "Title", title }, { "Body", body } }, [new(user, NotificationRecipientType.User, NotificationChannel.InApp, null, null), new(user, NotificationRecipientType.User, NotificationChannel.Push, null, null)], NotificationPriority.High, key, "Checkout", entity.ToString()), ct); }
    void Audit(string type, Guid? actor, Guid customer, Guid? subject, DateTime now) => db.OperationalAuditEvents.Add(new() { Id = Guid.NewGuid(), EventType = type, ActorUserId = actor, SubjectId = subject, MetadataJson = $"{{\"customerId\":\"{customer}\"}}", CorrelationId = Guid.NewGuid().ToString("N"), CreatedAtUtc = now });
    static FinancialJournal Journal(PurchaseTransaction p, CreatorPay.Domain.Services.CommissionCalculation c, DateTime now, bool merchantFunded, decimal customerRecoveryOffset) { var j = new FinancialJournal { Id = Guid.NewGuid(), Reference = $"FOUR-PARTY-{p.PublicTransactionId}", Description = "Approved four-party checkout", RelatedTransactionId = p.Id, CreatedAtUtc = now }; j.Lines.Add(Line(merchantFunded ? JournalAccount.MerchantWalletLiability : JournalAccount.PlatformTrialCreditExpense, JournalLineType.Debit, c.TotalCommissionAmount, now)); j.Lines.Add(Line(JournalAccount.CreatorPayable, JournalLineType.Credit, c.CreatorCommissionAmount, now)); if (c.CustomerCashbackAmount - customerRecoveryOffset > 0) j.Lines.Add(Line(JournalAccount.CustomerCashbackPayable, JournalLineType.Credit, c.CustomerCashbackAmount - customerRecoveryOffset, now)); if (customerRecoveryOffset > 0) j.Lines.Add(Line(JournalAccount.CustomerRecoveryReceivable, JournalLineType.Credit, customerRecoveryOffset, now)); j.Lines.Add(Line(JournalAccount.PlatformCommissionRevenue, JournalLineType.Credit, c.PlatformCommissionAmount, now)); j.Post(now); return j; }
    static FinancialJournalLine Line(JournalAccount a, JournalLineType t, decimal amount, DateTime now) => new() { Id = Guid.NewGuid(), Account = a, Type = t, Amount = amount, CurrencyCode = "ETB", Description = a.ToString(), CreatedAtUtc = now }; static string Hash(string x) => Convert.ToHexString(SHA256.HashData(Encoding.UTF8.GetBytes(x))); static void Key(string x) { if (string.IsNullOrWhiteSpace(x) || x.Length > 200) throw new ArgumentException("Idempotency-Key is required."); }
    static CheckoutDto Map(CheckoutSession x, string? qr = null) => new(x.Id, x.PublicCheckoutId, x.Status.ToString(), x.CustomerId, x.CampaignId, x.MerchantId, x.CreatorId, x.PurchaseAmount, x.ExpectedCreatorAmount, x.ExpectedCashbackAmount, x.ExpiresAtUtc, x.PurchaseTransactionId, qr); static CustomerPayoutDto Map(CustomerPayoutRequest p) => new(p.Id, p.PublicPayoutId, p.Amount, p.CurrencyCode, p.Status.ToString(), p.RequestedAtUtc, p.PaidAtUtc, p.ExternalReference);
}
